// Internal codepage table types. The tables themselves are generated by
// tools/gen_codepages.py into src/encoding/tables/.
#pragma once

#include <cstdint>

namespace tbcad::dxf::detail {

inline constexpr char16_t kUndefinedChar = 0xFFFD;
inline constexpr char16_t kLeadByte = 0xFFFF;

// Bytes 0x00-0x7F are ASCII. `high[b - 0x80]` is the UTF-16 unit for byte b,
// kUndefinedChar for an unassigned byte.
struct SingleByteTable {
    char16_t high[128];
};

// As above, but a `high` entry equal to kLeadByte starts a two-byte sequence:
// `pairs[(lead - leadMin) * (trailMax - trailMin + 1) + (trail - trailMin)]`, 0 = unassigned.
struct DoubleByteTable {
    char16_t high[128];
    std::uint8_t leadMin, leadMax, trailMin, trailMax;
    const char16_t* pairs;
};

extern const SingleByteTable kCp874;
extern const SingleByteTable kCp1250;
extern const SingleByteTable kCp1251;
extern const SingleByteTable kCp1252;
extern const SingleByteTable kCp1253;
extern const SingleByteTable kCp1254;
extern const SingleByteTable kCp1255;
extern const SingleByteTable kCp1256;
extern const SingleByteTable kCp1257;
extern const SingleByteTable kCp1258;
extern const DoubleByteTable kCp932;
extern const DoubleByteTable kCp936;
extern const DoubleByteTable kCp949;
extern const DoubleByteTable kCp950;

}  // namespace tbcad::dxf::detail
